import AVFoundation
import CoreML
import Foundation

let config = MLModelConfiguration()
config.computeUnits = .cpuOnly // Leave the GPU exclusively to the active training job.
let modelPath = "Models/Artifacts/silero-vad-b419383c55c1/silero-vad-unified-256ms-v6.2.1.mlmodelc"
let model = try MLModel(contentsOf: URL(fileURLWithPath: modelPath), configuration: config)
func array(_ values: [Float]) throws -> MLMultiArray {
    let output = try MLMultiArray(shape: [1, NSNumber(value: values.count)], dataType: .float32)
    for (index, value) in values.enumerated() { output[index] = NSNumber(value: value) }
    return output
}
func probabilities(_ samples: [Float]) throws -> [Double] {
    var context = [Float](repeating: 0, count: 64)
    var hidden = try array([Float](repeating: 0, count: 128))
    var cell = try array([Float](repeating: 0, count: 128))
    var values: [Double] = []
    for start in stride(from: 0, to: samples.count, by: 4096) {
        var chunk = Array(samples[start..<min(start + 4096, samples.count)])
        chunk += [Float](repeating: 0, count: 4096 - chunk.count)
        let output = try model.prediction(from: MLDictionaryFeatureProvider(dictionary: [
            "audio_input": try array(context + chunk), "hidden_state": hidden, "cell_state": cell]))
        guard let score = output.featureValue(for: "vad_output")?.multiArrayValue,
              let nextHidden = output.featureValue(for: "new_hidden_state")?.multiArrayValue,
              let nextCell = output.featureValue(for: "new_cell_state")?.multiArrayValue else {
            fatalError("Missing VAD outputs")
        }
        let value = score[0].doubleValue
        precondition(value.isFinite && (0...1).contains(value))
        values.append(value)
        hidden = nextHidden; cell = nextCell; context = Array(chunk.suffix(64))
    }
    return values
}
let fixture = ".build/audio-smoke/spoken-001.wav"
let file = try AVAudioFile(forReading: URL(fileURLWithPath: fixture), commonFormat: .pcmFormatFloat32, interleaved: false)
precondition(file.processingFormat.sampleRate == 16000 && file.processingFormat.channelCount == 1)
let buffer = AVAudioPCMBuffer(pcmFormat: file.processingFormat, frameCapacity: AVAudioFrameCount(file.length))!
try file.read(into: buffer)
let speech = Array(UnsafeBufferPointer(start: buffer.floatChannelData![0], count: Int(buffer.frameLength)))
var seed: UInt64 = 20260916
let noise: [Float] = (0..<32768).map { _ in
    seed = seed &* 6364136223846793005 &+ 1
    return (Float(seed >> 40) / Float(1 << 24) * 2 - 1) * 0.02
}
let silenceScores = try probabilities([Float](repeating: 0, count: 32768))
let noiseScores = try probabilities(noise)
let speechScores = try probabilities(speech)
let threshold = 0.85 // VadConfig.default in the pinned FluidAudio fork.
precondition(silenceScores.allSatisfy { $0 < threshold })
precondition(noiseScores.allSatisfy { $0 < threshold })
precondition(speechScores.contains { $0 >= threshold })
let report: [String: Any] = ["scope": "CPU-only model asset smoke with synthesized speech, silence and seeded white noise; not representative recognition or production SpeechGate evidence",
    "model": modelPath, "audioFixture": fixture, "threshold": threshold,
    "silenceProbabilities": silenceScores, "noiseProbabilities": noiseScores,
    "speechProbabilities": speechScores, "passed": true]
let data = try JSONSerialization.data(withJSONObject: report, options: [.sortedKeys, .prettyPrinted])
try data.write(to: URL(fileURLWithPath: ".build/vad-cpu-smoke.json"), options: .atomic)
print(String(decoding: data, as: UTF8.self))

