import AVFoundation
import XCTest
@testable import Recognition

final class SileroAssetSmokeTests: XCTestCase {
    func testProductionGateWithPinnedSileroAsset() async throws {
        let environment = ProcessInfo.processInfo.environment
        let model = URL(fileURLWithPath: try XCTUnwrap(environment["POPTART_VAD_SMOKE_MODEL"]))
        let audio = URL(fileURLWithPath: try XCTUnwrap(environment["POPTART_VAD_SMOKE_AUDIO"]))
        let gate = await SpeechGate.make(modelDirectory: model)
        let format = try XCTUnwrap(AVAudioFormat(standardFormatWithSampleRate: 16_000, channels: 1))
        func buffer(_ samples: [Float]) throws -> AVAudioPCMBuffer {
            let value = try XCTUnwrap(AVAudioPCMBuffer(pcmFormat: format, frameCapacity: AVAudioFrameCount(samples.count)))
            value.frameLength = value.frameCapacity
            let pointer = try XCTUnwrap(value.floatChannelData)[0]
            for (index, sample) in samples.enumerated() { pointer[index] = sample }
            return value
        }
        func flatten(_ buffers: [AVAudioPCMBuffer]) -> [Float] {
            buffers.flatMap { Array(UnsafeBufferPointer(start: $0.floatChannelData![0], count: Int($0.frameLength))) }
        }
        var random: UInt32 = 0x53494C45
        var noise: [Float] = []
        for _ in 0..<(8 * 4_096) {
            random = 1_664_525 &* random &+ 1_013_904_223
            noise.append((Float(random >> 8) / Float(1 << 24) * 2 - 1) * 0.02)
        }
        var filtered: [AVAudioPCMBuffer] = []
        // Deliberately misaligned capture buffers exercise exact recurrent windows.
        for start in stride(from: 0, to: noise.count, by: 1_536) {
            let input = try buffer(Array(noise[start..<min(start + 1_536, noise.count)]))
            filtered.append(contentsOf: await gate.gate(.init(buffer: input, audioActivity: nil)).buffers)
        }
        filtered.append(contentsOf: await gate.flush().buffers)
        let quiet = flatten(filtered)
        XCTAssertEqual(quiet.count, noise.count)
        XCTAssertTrue(quiet.allSatisfy { $0 == 0 }, "A missing/failed model passes noise through and must fail this probe")

        await gate.reset()
        let file = try AVAudioFile(forReading: audio, commonFormat: .pcmFormatFloat32, interleaved: false)
        XCTAssertEqual(file.processingFormat.sampleRate, 16_000)
        XCTAssertEqual(file.processingFormat.channelCount, 1)
        let recording = try XCTUnwrap(AVAudioPCMBuffer(pcmFormat: file.processingFormat, frameCapacity: AVAudioFrameCount(file.length)))
        try file.read(into: recording)
        let spoken = flatten([recording])
        filtered.removeAll()
        for start in stride(from: 0, to: spoken.count, by: 1_536) {
            let input = try buffer(Array(spoken[start..<min(start + 1_536, spoken.count)]))
            filtered.append(contentsOf: await gate.gate(.init(buffer: input, audioActivity: nil)).buffers)
        }
        filtered.append(contentsOf: await gate.flush().buffers)
        let delivered = flatten(filtered)
        XCTAssertEqual(delivered, spoken, "This authored speech fixture should survive byte-identically")
        print("Silero production gate: noiseFrames=\(quiet.count) zeroed; speechFrames=\(delivered.count) unchanged; tapFrames=1536")
    }
}
